  return (conservarCorchetes === true ? y : y.replace(/\[/g, '(').replace(/\]/g, ')')).replace(/<<<|>>>/g, '').replace(/[<>]+/g, '').replace(/[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g, ' ').replace(/\s+/g, ' ').trim();
