    .replace(/https?:\/\/\S+|www\.\S+|\b\S+\.(?:com|net|org|bo|io|app|me|link|ly)\b\S*/gi, ' ')
    .replace(/\d[\d\s.-]{3,}\d/g, ' ')
    .replace(/[`*_\\]/g, ' ');
