  const t = l.tipo !== 'otra' && EV_ROTULO_ANUNCIO[l.tipo] ? '[imagen: ' + EV_ROTULO_ANUNCIO[l.tipo].replace(/^Captura del /, '') + ']' : '[imagen' + (l.descripcion ? ': ' + evEnmascarar(l.descripcion).slice(0, 120) : '') + ']';
