    ultimosIds: ids.slice(-EV_TOPE_IDS), turnos: f && Number.isFinite(f.turnos) ? f.turnos : 0, ultimoMs: ultimoMs,
    noContactarMs: ven(f && f.noContactarMs) ? f.noContactarMs : 0, noContactar: ven(f && f.noContactarMs),
