    type: 'button', body: { text: cmRecorte(cuerpo, 1024) },
    action: { buttons: (botones || []).slice(0, 3).map((b) => ({ type: 'reply', reply: { id: cmRecorte(b.id, 200), title: cmRecorte(b.title, 20) } })) },
  } });
